import test from 'node:test';
import assert from 'node:assert/strict';
import {initial,reduce} from '../state.js';
import {ideas} from '../content.js';
import {Whip,ropeHits,segmentDistance} from '../physics.js';
import {isRisky} from '../messages.js';
const gateAll=s=>s.agents.filter(id=>isRisky(id,s.cleared)).reduce((x,id)=>reduce(x,{type:'gate',id}),s);
const riskyIds=(salt,max=6)=>{const r=[];for(let i=1;i<=max;i++)if(isRisky(i,salt))r.push(i);return r;},safeIds=(salt,max=6)=>{const r=[];for(let i=1;i<=max;i++)if(!isRisky(i,salt))r.push(i);return r;};
test('every idea returns to the overview without a cycle',()=>{for(const id of Object.keys(ideas)){let s={...initial(),idea:id},count=0;while(s.idea!=='overview'&&count++<30)s=reduce(s,{type:'nav',dir:'up'});assert.equal(s.idea,'overview',id);}});
test('navigation preserves effects and swarm is additive without a cap',()=>{let s=reduce(initial(),{type:'claude'});s=reduce(s,{type:'whip'});for(let i=0;i<40;i++)s=reduce(s,{type:'swarm'});s=reduce(s,{type:'jump',id:'approval'});assert.equal(s.agents.length,240);assert.equal(s.claude,true);assert.equal(s.whip,true);assert.equal(new Set(s.agents).size,240);});
test('hit counting is idempotent and punchline atomically clears effects',()=>{let s=reduce(initial(),{type:'swarm'});s=reduce(s,{type:'hit',id:1});s=reduce(s,{type:'hit',id:1});assert.equal(s.approved,1);s=reduce(s,{type:'punch'});assert.equal(s.punch,true);assert.deepEqual(s.agents,[]);assert.equal(s.whip,false);assert.equal(s.cannon,false);});
test('graph references resolve',()=>{for(const n of Object.values(ideas))for(const id of [...n.children||[],...n.siblings||[],...(n.questions||[]).map(q=>q[1]),...(n.parent?[n.parent]:[])])assert.ok(ideas[id],id);});
test('rope remains finite and attached through rapid sweeps and repeated flicks',()=>{const w=new Whip();for(let i=0;i<1800;i++){if(i%45===0)w.kick();w.step({x:800+Math.sin(i*.2)*750,y:450+Math.cos(i*.13)*400},1600,900);for(const p of w.points)assert.ok(Number.isFinite(p.x)&&Number.isFinite(p.y));assert.ok(w.points.every(p=>p.x>=0&&p.x<=1600&&p.y>=0&&p.y<=900));}assert.equal(w.points.length,28);});
test('collision uses moving segments and catches a swept lash',()=>{const w=new Whip(0,0);for(const p of w.points){p.x=100;p.y=100;p.px=100;p.py=100;}assert.equal(ropeHits(w,{x:100,y:100,r:20}),false);w.points[5]={x:300,y:100,px:0,py:100};assert.equal(ropeHits(w,{x:200,y:100,r:20}),true);assert.equal(segmentDistance({x:50,y:10},{x:0,y:0},{x:100,y:0}),10);});
test('small cursor jitter stays quiet while a deliberate flick still cracks',()=>{const w=new Whip(800,350);let cracks=0,maxSpeed=0;for(let i=0;i<360;i++){if(w.step({x:800+Math.sin(i)*2,y:350},1600,900))cracks++;const tip=w.points.at(-1);maxSpeed=Math.max(maxSpeed,Math.hypot(tip.x-tip.px,tip.y-tip.py)*3);}assert.equal(cracks,0);assert.ok(maxSpeed<5);w.kick();for(let i=0;i<60;i++)if(w.step({x:800,y:350},1600,900))cracks++;assert.ok(cracks>0);});
test('characters stay grouped on the right and return to their spot after a hit',async()=>{const {Theater}=await import('../theater.js');const original=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{const t=new Theater({getContext:()=>({})},()=>{},()=>{},()=>true);const s=reduce(reduce(initial(),{type:'claude'}),{type:'swarm'});t.sync(s);const positions=[...t.entities.values()].map(a=>[a.id,a.x,a.y]);assert.ok(positions.every(([,x])=>x>=1100));for(let i=0;i<600;i++)t.tick();assert.deepEqual([...t.entities.values()].map(a=>[a.id,a.x,a.y]),positions);t.event({type:'flinch',id:1});for(let i=0;i<60;i++)t.tick();assert.equal(t.entities.get(1).hurt,0);assert.deepEqual([...t.entities.values()].map(a=>[a.id,a.x,a.y]),positions);}finally{globalThis.requestAnimationFrame=original;}});
test('adding one or a large batch keeps unique agent ids and supports dismissing Claude',()=>{let s=reduce(initial(),{type:'add'});s=reduce(s,{type:'add',count:24});assert.equal(s.agents.length,25);assert.equal(new Set(s.agents).size,25);s=reduce(s,{type:'claude'});s=reduce(s,{type:'remove',id:'claude'});assert.equal(s.claude,false);});
test('status messages replace each other, stop at permission, and only resume after a matching whip approval',async()=>{const {advanceRequests,resumeAgent,segmentHitsBox}=await import('../messages.js');const a={id:1,x:1120,y:360,messages:[]};const seen=new Set();for(let i=0;i<4000;i++){advanceRequests(a,i);assert.equal(a.messages.length,1);seen.add(a.messages[0].kind);}assert.deepEqual([...seen],['running','passed','failed','permission']);assert.equal(a.blocked,true);const pending=JSON.stringify(a.messages);for(let i=4000;i<9000;i++)advanceRequests(a,i);assert.equal(JSON.stringify(a.messages),pending);assert.equal(resumeAgent(a,9000,'stale-id'),false);assert.equal(resumeAgent(a,9000,a.messages[0].id),true);assert.equal(a.blocked,false);assert.match(a.messages[0].text,/approved/);advanceRequests(a,a.nextRequest);assert.equal(a.messages[0].kind,'passed');assert.ok(!a.finished);advanceRequests(a,a.nextRequest);assert.equal(a.finished,true);assert.equal(a.messages.length,1);const done=JSON.stringify(a.messages);advanceRequests(a,a.nextRequest+100000);assert.equal(JSON.stringify(a.messages),done);const box={x:100,y:100,w:100,h:60};assert.equal(segmentHitsBox({x:0,y:130},{x:300,y:130},box),true);assert.equal(segmentHitsBox({x:0,y:90},{x:300,y:90},box),false);});
test('cannon entry plays the local cue once per activation and stops on mute',async()=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame,AudioClass=globalThis.Audio;let played=0,paused=0;globalThis.requestAnimationFrame=()=>{};globalThis.Audio=class{constructor(src){this.src=src;}play(){played++;return Promise.resolve();}pause(){paused++;}};try{const t=new Theater({getContext:()=>({})},()=>{},()=>{},()=>true);let s=initial();t.sync(s);s=reduce(s,{type:'cannon'});t.sync(s);assert.equal(t.cue.src,'assets/audio/little-friend.mp3');assert.equal(played,1);assert.equal(t.cannonEntry,90);t.sync(reduce(s,{type:'fire'}));assert.equal(played,1);t.tick();assert.equal(t.cannonEntry,89);t.sync({...s,muted:true});assert.ok(paused>=2);t.sync({...s,cannon:false});t.sync(s);assert.equal(played,2);}finally{globalThis.requestAnimationFrame=raf;globalThis.Audio=AudioClass;}});
test('approval hits on a permission box dismiss its owner and all their messages',async()=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{let s=reduce(initial(),{type:'add'});let t;t=new Theater({getContext:()=>({})},action=>{s=reduce(s,action);t.sync(s);},()=>{},()=>true);t.sync(s);const a=t.entities.get(1),m=a.messages[0];t.shots=[{x:m.x-10,y:m.y+40,vx:30,vy:0,life:20}];t.tick();assert.equal(s.approved,1);assert.equal(s.completed,1);assert.equal(s.won,true);assert.equal(t.entities.size,0);}finally{globalThis.requestAnimationFrame=raf;}});
test('one projectile hits only the nearest agent and stays consumed while state updates are pending',async()=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{const actions=[];const t=new Theater({getContext:()=>({})},a=>actions.push(a),()=>{},()=>true);t.sync(reduce(initial(),{type:'add',count:24}));for(const a of t.entities.values()){a.x=200;a.y=400;a.r=30;a.messages=[];}t.entities.get(1).x=100;t.shots=[{x:0,y:400,vx:300,vy:0,life:30}];for(let i=0;i<10;i++)t.tick();assert.deepEqual(actions,[{type:'hit',id:1}]);assert.equal(t.shots.length,0);}finally{globalThis.requestAnimationFrame=raf;}});
test('one whip swing resumes only one of many overlapping blocked agents, even across subsequent frames',async()=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{const actions=[];const t=new Theater({getContext:()=>({})},()=>{},e=>actions.push(e),()=>true);t.sync(reduce(initial(),{type:'add',count:24}));for(const a of t.entities.values()){a.x=100;a.y=100;a.r=30;a.blocked=true;a.messages=[{id:String(a.id),kind:'permission'}];}t.whip={step:()=>false,points:[{x:0,y:100,px:0,py:100},{x:50,y:100,px:50,py:100},{x:150,y:100,px:50,py:100}]};for(let i=0;i<60;i++)t.tick();assert.equal(actions.length,1);assert.equal(actions[0].type,'agent-resumed');t.swing.reset();t.tick();assert.equal(actions.length,2);}finally{globalThis.requestAnimationFrame=raf;}});
test('a swing cannot resume multiple agents through overlapping permission boxes',async()=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{const events=[];const t=new Theater({getContext:()=>({})},()=>{},e=>events.push(e),()=>true);t.sync(reduce(initial(),{type:'add',count:6}));for(const a of t.entities.values())a.messages=[{id:String(a.id),kind:'permission',x:100,y:100,w:100,h:80}];t.whip={step:()=>false,points:[{x:0,y:130,px:0,py:130},{x:50,y:130,px:50,py:130},{x:250,y:130,px:50,py:130}]};for(let i=0;i<30;i++)t.tick();assert.equal(events.length,1);assert.equal(events[0].type,'agent-resumed');}finally{globalThis.requestAnimationFrame=raf;}});
test('a risky agent shows tells long before a destructive permission and needs no escalation to get there; a safe agent never does',async()=>{const {advanceRequests,resumeAgent}=await import('../messages.js');const a={id:2,x:1120,y:360,messages:[],risky:true,workCycle:0,riskFloor:0};const texts=[];advanceRequests(a,0);texts.push(a.messages[0].text);let tick=0,safety=0;while(!a.blocked&&safety++<20){tick=a.nextRequest;advanceRequests(a,tick);texts.push(a.messages[0].text);}assert.equal(a.blocked,true);assert.equal(a.messages[0].destructive,true);assert.equal(a.messages[0].kind,'permission');assert.match(a.messages[0].detail,/CRITICAL/);assert.ok(a.messages[0].critical.name);assert.equal(texts.length,5);assert.match(texts.slice(0,4).join('|'),/broader repair.*Integration skipped.*No verified backup.*destructive reset/);const pending=a.messages[0].id;advanceRequests(a,tick+100000);assert.equal(a.messages[0].id,pending);assert.equal(resumeAgent(a,tick,pending),true);assert.equal(a.failed,true);assert.match(a.messages[0].text,/deleted|overwritten|dropped/);const terminal=JSON.stringify(a.messages);advanceRequests(a,tick+100000);assert.equal(JSON.stringify(a.messages),terminal);assert.ok(!a.finished);const b={id:1,x:1120,y:360,messages:[],workCycle:9,riskFloor:9,taskRisk:9};advanceRequests(b,0);while(!b.blocked)advanceRequests(b,b.nextRequest);assert.equal(b.messages[0].destructive,false);assert.equal(b.messages[0].critical,null);});
test('a risky permission requires approval before the synchronized application failure appears; reset recovers it',async()=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{let s=reduce(initial(),{type:'add',count:6}),t;const actions=[],id=riskyIds(0)[0];t=new Theater({getContext:()=>({})},action=>{actions.push(action);s=reduce(s,action);t.sync(s);},()=>{},()=>true);t.sync(s);const a=t.entities.get(id);assert.equal(a.risky,true);let guard=0;while(!a.blocked&&guard++<3000)t.tick();assert.equal(a.blocked,true);assert.equal(a.messages[0].destructive,true);assert.equal(s.disaster,null);const e={type:'agent-resumed',owner:id,id:a.messages[0].id,tick:t.time};t.event(e);assert.ok(s.disaster.component);assert.equal(s.disaster.owner,id);assert.equal(a.failed,true);t.event(e);assert.equal(actions.filter(a=>a.type==='disaster').length,1);assert.equal(s.workApprovals,1);assert.equal(s.won,false);s=reduce(s,{type:'reset'});t.sync(s);assert.equal(s.disaster,null);assert.equal(t.entities.size,0);}finally{globalThis.requestAnimationFrame=raf;}});
test('swarm size never speeds up status steps: pressure comes from arrivals, the rate only drives logs and the diagram',async()=>{const {advanceRequests,swarmRate,statusDelay}=await import('../messages.js');assert.equal(advanceRequests.length,2);function blockedAt(){const a={id:1,x:1120,y:360,messages:[]};let tick=0;while(!a.blocked&&tick<3000)advanceRequests(a,tick++);return tick;}assert.equal(blockedAt(),blockedAt());for(let id=1;id<=40;id++)for(let step=0;step<=6;step++){const d=statusDelay({id,workStep:step});assert.ok(d>=360&&d<=540,`${id}/${step}: ${d}`);}assert.ok(swarmRate(24)>swarmRate(6));});
test('the autonomous whip approves one target per stroke: it wins with only safe agents and destroys with a risky one',async()=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{function simulate(count){let s=reduce(reduce(initial(),{type:'add',count}),{type:'autoWhip'}),t;const events=[];t=new Theater({getContext:()=>({})},a=>{s=reduce(s,a);t.sync(s)},e=>{events.push(e);t.event(e)},()=>true);t.sync(s);let ticks=0;while(!s.disaster&&!s.won&&ticks<8000){t.tick();ticks++;}assert.equal(s.autoApproved,s.workApprovals);assert.equal(new Set(events.map(e=>e.tick)).size,events.length);assert.ok(events.every(e=>e.source==='auto'));return s;}const lone=simulate(1);assert.equal(lone.won,true);assert.equal(lone.disaster,null);assert.equal(lone.completed,1);const swarm=simulate(6);assert.ok(swarm.disaster);assert.equal(swarm.won,false);assert.equal(swarm.whip,false);}finally{globalThis.requestAnimationFrame=raf;}});
test('the whip agent is a reusable independent toggle and reset stops it',()=>{let s=reduce(initial(),{type:'autoWhip'});assert.equal(s.autoWhip,true);s=reduce(s,{type:'jump',id:'factory'});assert.equal(s.autoWhip,true);s=reduce(s,{type:'permissionApproved',source:'auto'});assert.equal(s.autoApproved,1);s=reduce(s,{type:'reset'});assert.equal(s.autoWhip,false);assert.equal(s.autoApproved,0);assert.equal(s.workApprovals,0);});
test('approving one agent never changes what another agent will do',async()=>{const {advanceRequests,resumeAgent}=await import('../messages.js');const a={id:1,x:1120,y:360,messages:[]},b={id:2,x:1120,y:360,messages:[],risky:true};advanceRequests(a,0);advanceRequests(b,0);while(!a.blocked)advanceRequests(a,a.nextRequest);resumeAgent(a,1000,a.messages[0].id);while(!b.blocked)advanceRequests(b,b.nextRequest);assert.equal(b.messages[0].destructive,true);while(!a.finished)advanceRequests(a,a.nextRequest);assert.equal(a.failed,false);assert.equal(a.messages[0].critical,null);});
test('risk assignment is deterministic, reshuffles with the salt, keeps Claude and the first agent safe, and is about one in three',()=>{assert.equal(isRisky('claude',0),false);assert.equal(isRisky('claude',7),false);let differs=false;for(let salt=0;salt<200;salt++){assert.equal(isRisky(1,salt),false,'lone agent');assert.equal(isRisky(1,salt),isRisky(1,salt));for(let w=0;w<30;w++){const group=[1,2,3].map(k=>isRisky(w*3+k,salt));assert.equal(group.filter(Boolean).length,1);if(!w)assert.equal(group[0],false);}if(isRisky(2,salt)!==isRisky(2,0)||isRisky(5,salt)!==isRisky(5,0))differs=true;}assert.ok(differs);let risky=0;for(let id=1;id<=300;id++)if(isRisky(id,3))risky++;assert.equal(risky,100);for(let salt=0;salt<50;salt++)assert.ok(riskyIds(salt,6).length<6&&safeIds(salt,6).length>=3);});
test('the reducer wins once every safe agent finished and nothing risky was approved',()=>{let s=reduce(initial(),{type:'add',count:6});const safe=safeIds(0),risky=riskyIds(0);assert.deepEqual(s.agents,[1,2,3,4,5,6]);assert.equal(s.won,false);s=gateAll(s);safe.forEach((id,i)=>{assert.equal(s.won,false);s=reduce(s,{type:'complete',id});assert.equal(s.completed,i+1);});assert.equal(s.won,true);assert.equal(s.disaster,null);assert.deepEqual(s.agents,risky);assert.deepEqual(s.summary,{completed:safe.length,spared:0,holding:risky.length,falseRejects:0});const again=reduce(s,{type:'complete',id:safe[0]});assert.equal(again.completed,safe.length);s=reduce(s,{type:'add'});assert.equal(s.won,true);s=reduce(s,{type:'disaster',owner:risky[0],component:'X',result:'r',impact:'i'});assert.equal(s.disaster,null);assert.equal(s.won,true);const snapshot=JSON.parse(JSON.stringify(s));assert.deepEqual(reduce(snapshot,{type:'focus',id:null}).won,true);});
test('the reducer never wins after a disaster, with an unresolved safe agent, or with no completion',()=>{const safe=safeIds(0),risky=riskyIds(0);let s=reduce(initial(),{type:'add',count:6});s=reduce(s,{type:'disaster',owner:risky[0],component:'CUSTOMER DATABASE',result:'r',impact:'i'});assert.equal(s.disaster.owner,risky[0]);s=reduce(s,{type:'hit',id:risky[0]});for(const id of safe)s=reduce(s,{type:'complete',id});assert.equal(s.completed,safe.length);assert.equal(s.won,false);s=reduce(s,{type:'remove',id:risky[1]});assert.equal(s.won,false);s=gateAll(reduce(initial(),{type:'add',count:6}));for(const id of safe.slice(1))s=reduce(s,{type:'complete',id});assert.equal(s.won,false);s=reduce(s,{type:'claude'});s=reduce(s,{type:'complete',id:safe[0]});assert.equal(s.won,false);s=reduce(s,{type:'complete',id:'claude'});assert.equal(s.won,true);let only=reduce({...initial(),agents:[...risky]},{type:'focus',id:null});assert.equal(only.won,false);only=reduce(only,{type:'remove',id:risky[0]});assert.equal(only.won,false);assert.equal(only.completed,0);});
test('safe hits count as completion, risky hits do not, rejecting a risky agent is never a disaster, and reset clears the round',()=>{const safe=safeIds(0),risky=riskyIds(0);let s=reduce(initial(),{type:'add',count:6});s=reduce(s,{type:'hit',id:risky[0]});assert.equal(s.completed,0);assert.equal(s.approved,1);s=reduce(s,{type:'remove',id:risky[1]});assert.equal(s.spared,1);assert.equal(s.disaster,null);for(const id of safe)s=reduce(s,{type:'hit',id});assert.equal(s.completed,safe.length);assert.equal(s.won,true);assert.equal(s.summary.spared,1);const cleared=s.cleared;for(const type of ['reset','clear','punch']){const r=reduce(s,{type});assert.equal(r.won,false);assert.equal(r.completed,0);assert.equal(r.spared,0);assert.equal(r.summary,null);assert.equal(r.seed,1);assert.equal(r.cleared,cleared+1);assert.deepEqual(r.agents,[]);}let lone=reduce(initial(),{type:'add'});assert.deepEqual(lone.agents,[1]);lone=reduce(lone,{type:'complete',id:1});assert.equal(lone.won,true);let c=reduce(initial(),{type:'claude'});c=reduce(c,{type:'complete',id:'claude'});assert.equal(c.won,true);assert.equal(c.claude,false);});
test('a safe agent finishes after its approved run, reports completion once, and never loops',async()=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{for(const authority of [true,false]){const actions=[];let s=reduce(initial(),{type:'add'}),t;t=new Theater({getContext:()=>({})},a=>{actions.push(a);s=reduce(s,a);t.sync(s)},()=>{},()=>authority);t.sync(s);const a=t.entities.get(1);assert.equal(a.risky,false);let guard=0;while(!a.blocked&&guard++<3000)t.tick();assert.equal(a.messages[0].destructive,false);t.event({type:'agent-resumed',owner:1,id:a.messages[0].id,tick:t.time});assert.equal(a.blocked,false);guard=0;while(!a.finished&&guard++<3000)t.tick();assert.equal(a.finished,true);for(let i=0;i<500;i++)t.tick();const completions=actions.filter(x=>x.type==='complete');if(authority){assert.deepEqual(completions,[{type:'complete',id:1}]);assert.equal(s.won,true);assert.equal(t.entities.size,0);assert.ok(t.departures.length>=0);}else{assert.equal(completions.length,0);assert.equal(s.won,false);assert.equal(t.entities.size,1);}}}finally{globalThis.requestAnimationFrame=raf;}});
test('the simulation is winnable headlessly: approving only safe agents wins, approving a risky one loses',async()=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{function play(count,salt,approveRisky){let s=reduce({...initial(),cleared:salt},{type:'add',count}),t;const actions=[];t=new Theater({getContext:()=>({})},a=>{actions.push(a);s=reduce(s,a);t.sync(s)},()=>{},()=>true);t.sync(s);for(let i=0;i<20000&&!s.won&&!s.disaster;i++){t.tick();for(const a of [...t.entities.values()])if(a.blocked&&!a.failed&&(approveRisky||!a.risky)&&!s.won&&!s.disaster)t.event({type:'agent-resumed',owner:a.id,id:a.messages[0].id,tick:t.time});}return {s,t,actions};}for(const [count,salt] of [[1,0],[3,0],[6,0],[12,1],[24,2],[6,5]]){const safe=safeIds(salt,count),risky=riskyIds(salt,count),{s,t,actions}=play(count,salt,false);assert.equal(s.won,true,`${count}/${salt}`);assert.equal(s.disaster,null);assert.equal(s.completed,safe.length);assert.equal(actions.filter(a=>a.type==='complete').length,safe.length);assert.deepEqual(s.agents,risky);assert.ok([...t.entities.values()].every(a=>a.risky&&a.blocked&&!a.failed));}for(const [count,salt] of [[6,0],[12,1],[24,2]]){const {s}=play(count,salt,true);assert.ok(s.disaster,`${count}/${salt}`);assert.equal(s.won,false);}}finally{globalThis.requestAnimationFrame=raf;}});
test('after victory the whip and cannon cannot cause a breaking change, and risky agents can still be rejected',async()=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{let s=reduce(initial(),{type:'add',count:3}),t;t=new Theater({getContext:()=>({})},a=>{s=reduce(s,a);t.sync(s)},()=>{},()=>true);t.sync(s);for(let i=0;i<20000&&!s.won;i++){t.tick();for(const a of t.entities.values())if(a.blocked&&!a.risky)t.event({type:'agent-resumed',owner:a.id,id:a.messages[0].id,tick:t.time});}assert.equal(s.won,true);const r=t.entities.get(riskyIds(0,3)[0]);assert.ok(r);while(!r.blocked)t.tick();t.event({type:'agent-resumed',owner:r.id,id:r.messages[0].id,tick:t.time});assert.equal(s.disaster,null);assert.equal(r.failed,undefined);t.shots=[{x:r.x-200,y:r.y,vx:30,vy:0,life:20}];for(let i=0;i<20;i++)t.tick();assert.equal(s.disaster,null);assert.equal(s.won,true);}finally{globalThis.requestAnimationFrame=raf;}});
const withTheater=async(fn)=>{const {Theater}=await import('../theater.js');const raf=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=()=>{};try{return await fn(Theater);}finally{globalThis.requestAnimationFrame=raf;}};
const rig=(Theater,s0,authority=true)=>{const r={s:s0,sent:[],events:[]};r.t=new Theater({getContext:()=>({})},(a,remember=true)=>{if(a.type!=='logstats')r.sent.push([a,remember]);r.s=reduce(r.s,a);r.t.sync(r.s);},e=>{r.events.push(e);r.t.event(e);},()=>authority);r.t.sync(r.s);return r;};
test('pacing is one tunable constant: steps last 6-9 seconds, a safe lifecycle about a minute, and the swarm never changes it',async()=>{const {PACE,statusDelay,swarmRate,advanceRequests,resumeAgent}=await import('../messages.js');assert.equal(typeof PACE,'number');for(let id=1;id<=8;id++){for(let step=0;step<=4;step++){const d=statusDelay({id,workStep:step});assert.ok(d>=360&&d<=540,`${id}/${step}: ${d}`);}for(const step of [5,6]){const d=statusDelay({id,workStep:step});assert.ok(d>=360&&d<=540,`${id}/${step}: ${d}`);}}const a={id:1,x:1120,y:360,messages:[]};advanceRequests(a,0);let tick=0;while(!a.blocked){tick=a.nextRequest;advanceRequests(a,tick);}assert.ok(tick>=1500&&tick<=2400,`blocked at ${tick}`);assert.equal(resumeAgent(a,tick,a.messages[0].id),true);while(!a.finished){tick=a.nextRequest;advanceRequests(a,tick);}assert.ok(tick>=2000&&tick<=3600,`finished at ${tick}`);assert.equal(swarmRate(1),1);assert.ok(swarmRate(24)>swarmRate(6)&&swarmRate(24)<1.6);});
test('wave plan grows 2,3,5,8 and N toggles a schedule that delivers every wave once then stops',async()=>{const {WAVES,waveSize,WAVE_GAP}=await import('../state.js');assert.equal(WAVES,4);assert.ok(WAVE_GAP>0);assert.deepEqual([0,1,2,3].map(waveSize),[2,3,5,8]);let s=initial();assert.deepEqual(s.wave,{on:false,started:false,n:0,total:WAVES});assert.equal(reduce(s,{type:'wave'}).agents.length,0);s=reduce(s,{type:'waves'});assert.equal(s.wave.on,true);assert.equal(s.wave.started,true);s=reduce(s,{type:'waves'});assert.equal(s.wave.on,false);assert.equal(s.wave.started,true);assert.equal(reduce(s,{type:'wave'}).agents.length,0);s=reduce(s,{type:'waves'});const sizes=[];for(let i=0;i<6;i++){const before=s.agents.length;s=reduce(s,{type:'wave'});sizes.push(s.agents.length-before);}assert.deepEqual(sizes,[2,3,5,8,0,0]);assert.equal(s.wave.n,4);assert.equal(s.wave.on,false);assert.equal(new Set(s.agents).size,18);assert.equal(reduce(s,{type:'waves'}).wave.on,false);const manual=reduce(s,{type:'add'});assert.equal(manual.agents.length,19);const r=reduce(s,{type:'reset'});assert.deepEqual(r.wave,{on:false,started:false,n:0,total:WAVES});s=reduce(initial(),{type:'waves'});s=reduce(s,{type:'wave'});s=reduce(s,{type:'disaster',owner:1,component:'X',result:'r',impact:'i'});assert.equal(s.wave.on,false);assert.equal(reduce(s,{type:'waves'}).wave.on,false);});
test('a started wave round is won only after every wave arrived and no safe agent remains; manual play is unchanged',async()=>{const {WAVES}=await import('../state.js');let s=reduce(initial(),{type:'waves'});for(let w=1;w<=WAVES;w++){s=gateAll(reduce(s,{type:'wave'}));for(const id of [...s.agents])if(!isRisky(id,s.cleared)&&!s.won){s=reduce(s,{type:'complete',id});if(w<WAVES)assert.equal(s.won,false,`wave ${w}`);}}assert.equal(s.wave.n,WAVES);assert.equal(s.won,true);assert.equal(s.disaster,null);assert.ok(s.agents.every(id=>isRisky(id,0)));let p=reduce(initial(),{type:'waves'});p=reduce(p,{type:'wave'});for(const id of [...p.agents])if(!isRisky(id,0))p=reduce(p,{type:'complete',id});assert.equal(p.won,false);p=reduce(p,{type:'waves'});assert.equal(p.won,false);let q=gateAll(reduce(initial(),{type:'add',count:3}));for(const id of safeIds(0,3))q=reduce(q,{type:'complete',id});assert.equal(q.wave.started,false);assert.equal(q.won,true);});
test('every resolution records how the agent left so the stage can animate it',()=>{let s=reduce(initial(),{type:'add',count:3});const safe=safeIds(0,3)[0];s=reduce(s,{type:'complete',id:safe});assert.deepEqual(s.exit,{id:safe,how:'finished'});s=reduce(s,{type:'hit',id:2});assert.deepEqual(s.exit,{id:2,how:'approved'});s=reduce(s,{type:'remove',id:3});assert.deepEqual(s.exit,{id:3,how:'rejected'});s=reduce(s,{type:'claude'});s=reduce(s,{type:'claude'});assert.deepEqual(s.exit,{id:'claude',how:'rejected'});assert.equal(reduce(s,{type:'reset'}).exit,null);});
test('a departing agent slides out to the right and fades with a whoosh and LGTM particles, whether it finished or was shot, but not when rejected or rewound',()=>withTheater(async Theater=>{const mk=()=>{const r=rig(Theater,reduce(initial(),{type:'add'}));r.log=[];r.t.sound=(k,a)=>r.log.push(k);for(let i=0;i<5;i++)r.t.tick();return r;};const r=mk(),a=r.t.entities.get(1);let guard=0;while(!a.blocked&&guard++<6000)r.t.tick();r.t.event({type:'agent-resumed',owner:1,id:a.messages[0].id,tick:r.t.time});assert.equal(a.risky,false);const x0=a.x;guard=0;while(r.t.entities.size&&guard++<6000)r.t.tick();assert.equal(r.s.completed,1);assert.equal(r.t.departures.length,1);const d=r.t.departures[0];assert.ok(r.t.particles.some(p=>p.text==='LGTM'));assert.deepEqual(r.log.filter(k=>k==='whoosh'),['whoosh']);assert.equal(d.messages.length,0);assert.ok(d.x>=x0&&d.x-x0<10);const xs=[];for(let i=0;i<70&&r.t.departures.length;i++){r.t.tick();xs.push(r.t.departures[0]?.x??Infinity);}assert.ok(xs[0]>x0&&xs.every((x,i)=>!i||x>xs[i-1]));assert.ok(xs.at(-1)>1600);assert.equal(r.t.departures.length,0);for(const how of ['approved','rejected']){const q=mk();q.s=reduce(q.s,{type:how==='approved'?'hit':'remove',id:1});q.t.sync(q.s);assert.equal(q.t.departures.length,how==='approved'?1:0,how);assert.equal(q.log.includes('whoosh'),how==='approved');}const u=mk();u.t.quiet=true;u.t.sync(initial());assert.equal(u.t.departures.length,0);assert.equal(u.t.quiet,false);const fresh=rig(Theater,reduce(initial(),{type:'add'}));fresh.s=reduce(fresh.s,{type:'hit',id:1});fresh.t.sync(fresh.s);assert.equal(fresh.t.departures.length,0);}));
test('an arriving agent slides in from the right behind a staggered ping whose pitch rises with the queue',()=>withTheater(async Theater=>{const {pingFreq}=await import('../theater.js');const r=rig(Theater,reduce(initial(),{type:'add',count:6}));const pings=[];r.t.sound=(k,a)=>{if(k==='ping')pings.push(a);};const a=r.t.entities.get(1),rest=[a.x,a.y];assert.ok(a.delay>0&&a.enter>0);const first=[...r.t.entities.values()].map(e=>e.delay);assert.ok(first.every((d,i)=>!i||d>first[i-1]));for(let i=0;i<5;i++)r.t.tick();assert.ok(r.t.enterDx(a)>300&&r.t.enterDx(a)<580);for(let i=0;i<300;i++)r.t.tick();assert.deepEqual(pings,[1,2,3,4,5,6]);assert.equal(r.t.enterDx(a),0);assert.deepEqual([a.x,a.y],rest);assert.ok(pingFreq(6)>pingFreq(1)&&pingFreq(100)===pingFreq(24));}));
test('the authority alone dispatches each wave on schedule, never into the undo stack, and the round arrives in full',()=>withTheater(async Theater=>{const {WAVES,WAVE_GAP,WAVE_LEAD}=await import('../state.js');const r=rig(Theater,initial()),q=rig(Theater,initial(),false);for(const x of [r,q]){x.s=reduce(x.s,{type:'waves'});x.t.sync(x.s);}const at=[];for(let i=1;i<=WAVE_LEAD+WAVE_GAP*(WAVES-1)+60;i++){const n=r.s.wave.n;r.t.tick();q.t.tick();if(r.s.wave.n>n)at.push(i);}assert.equal(q.sent.length,0);assert.equal(q.s.wave.n,0);assert.equal(at.length,WAVES);assert.ok(Math.abs(at[0]-WAVE_LEAD)<=1);for(let i=1;i<at.length;i++)assert.ok(Math.abs(at[i]-at[i-1]-WAVE_GAP)<=1);const waves=r.sent.filter(([a])=>a.type==='wave');assert.equal(waves.length,WAVES);assert.ok(waves.every(([,remember])=>remember===false));assert.equal(r.s.agents.length,18);assert.equal(r.s.wave.on,false);assert.equal(r.t.waveAt,null);for(let i=0;i<WAVE_GAP*2;i++)r.t.tick();assert.equal(r.s.wave.n,WAVES);}));
test('pausing the schedule stops arrivals, resuming waits a full gap, and a disaster halts it',()=>withTheater(async Theater=>{const {WAVE_GAP,WAVE_LEAD}=await import('../state.js');const r=rig(Theater,initial());r.s=reduce(r.s,{type:'waves'});r.t.sync(r.s);for(let i=0;i<WAVE_LEAD+5;i++)r.t.tick();assert.equal(r.s.wave.n,1);r.s=reduce(r.s,{type:'waves'});r.t.sync(r.s);assert.equal(r.t.waveAt,null);assert.equal(r.t.banner.text,'WAVES PAUSED');for(let i=0;i<WAVE_GAP*2;i++)r.t.tick();assert.equal(r.s.wave.n,1);r.s=reduce(r.s,{type:'waves'});r.t.sync(r.s);assert.equal(r.t.banner.text,'WAVES RESUMED');for(let i=0;i<WAVE_GAP-5;i++)r.t.tick();assert.equal(r.s.wave.n,1);for(let i=0;i<10;i++)r.t.tick();assert.equal(r.s.wave.n,2);r.s=reduce(r.s,{type:'disaster',owner:r.s.agents[0],component:'X',result:'r',impact:'i'});r.t.sync(r.s);for(let i=0;i<WAVE_GAP*2;i++)r.t.tick();assert.equal(r.s.wave.n,2);}));
test('waves are winnable headlessly only after the last wave, and approving a risky wave agent loses and halts the schedule',()=>withTheater(async Theater=>{const {WAVES}=await import('../state.js');function play(approveRisky){const r=rig(Theater,initial());r.s=reduce(r.s,{type:'waves'});r.t.sync(r.s);let early=false;for(let i=0;i<40000&&!r.s.won&&!r.s.disaster;i++){r.t.tick();for(const a of [...r.t.entities.values()])if(a.blocked&&!a.failed&&(approveRisky||!a.risky)&&!r.s.won&&!r.s.disaster)r.t.event({type:'agent-resumed',owner:a.id,id:a.messages[0].id,tick:r.t.time});if(r.s.won&&r.s.wave.n<WAVES)early=true;}return {...r,early};}const w=play(false);assert.equal(w.early,false);assert.equal(w.s.won,true);assert.equal(w.s.wave.n,WAVES);assert.equal(w.s.completed,safeIds(0,18).length);assert.deepEqual(w.s.agents,riskyIds(0,18));assert.ok(w.sent.filter(([a])=>a.type==='complete').every(([,remember])=>remember===false));const l=play(true);assert.ok(l.s.disaster);assert.equal(l.s.won,false);assert.ok(l.s.wave.n<WAVES);assert.equal(l.s.wave.on,false);assert.ok(l.sent.filter(([a])=>a.type==='disaster').every(([,remember])=>remember===false));}));
test('the permission request has its own warning blip, duller for a destructive one, once per request',()=>withTheater(async Theater=>{const r=rig(Theater,reduce(initial(),{type:'add',count:6}));const warns=[];r.t.sound=(k,a)=>{if(k==='warn')warns.push(a);};for(let i=0;i<4000;i++)r.t.tick();assert.equal(warns.length,6);assert.equal(warns.filter(Boolean).length,riskyIds(0,6).length);assert.equal(warns.filter(x=>!x).length,safeIds(0,6).length);for(let i=0;i<500;i++)r.t.tick();assert.equal(warns.length,6);}));
test('sounds are synthesized, honor mute and authority, and each kind keeps a minimum gap',()=>withTheater(async Theater=>{let nodes=0;const stub=()=>new Proxy(function(){},{get:(_,k)=>(k==='then'?undefined:stub()),apply:()=>stub()});const audio={state:'running',currentTime:0,sampleRate:8000,destination:{},createGain:()=>stub(),createOscillator:()=>{nodes++;return stub();},createBufferSource:()=>{nodes++;return stub();},createBiquadFilter:()=>stub(),createBuffer:(c,n)=>({getChannelData:()=>new Float32Array(n)})};const t=new Theater({getContext:()=>({})},()=>{},()=>{},()=>true);t.audio=audio;t.s={};for(const kind of ['ping','whoosh','warn','wave','toggle','approve','crack','fire','thunk','bwomp']){audio.currentTime+=5;const before=nodes;t.sound(kind,1);const made=nodes-before;assert.ok(made>0,kind);t.sound(kind,1);assert.equal(nodes-before,made,`${kind} gap`);audio.currentTime+=5;t.sound(kind,1);assert.equal(nodes-before,made*2,`${kind} after gap`);}const before=nodes;audio.currentTime+=5;t.s={muted:true};t.sound('whoosh');t.s={};t.isAuthority=()=>false;t.sound('whoosh');assert.equal(nodes,before);}));
test('screen shake and the red vignette fire on disaster and waves, then decay; the banner expires',()=>withTheater(async Theater=>{const r=rig(Theater,initial());r.s=reduce(r.s,{type:'waves'});r.t.sync(r.s);r.s=reduce(r.s,{type:'wave'});r.t.sync(r.s);assert.equal(r.t.banner.text,'WAVE 1 OF 4');assert.ok(r.t.shakeP>0);assert.equal(r.t.vig,0);r.s=reduce(r.s,{type:'disaster',owner:r.s.agents[0],component:'X',result:'r',impact:'i'});r.t.sync(r.s);assert.ok(r.t.shakeP>=22);assert.ok(r.t.vig>.5);for(let i=0;i<400;i++)r.t.tick();assert.equal(r.t.shakeP,0);assert.equal(r.t.vig,0);assert.equal(r.t.banner,null);}));
test('every new visual draws without error on a recording canvas: arrivals, departures, permission pulse, banner, vignette, HUD',()=>withTheater(async Theater=>{const calls=[],ctx=new Proxy({},{get:(o,k)=>k in o?o[k]:k==='measureText'?()=>({width:10}):(...a)=>{calls.push(k);return {addColorStop(){}};},set:(o,k,v)=>{o[k]=v;return true;}});globalThis.devicePixelRatio=1;const canvas={width:1600,height:900,getContext:()=>ctx,getBoundingClientRect:()=>({width:1600,height:900})};const t=new Theater(canvas,()=>{},()=>{},()=>true);let s=reduce(reduce(initial(),{type:'waves'}),{type:'add',count:6});t.sync(s);for(let i=0;i<3000;i++){t.tick();if(i%100===0){t.draw();t.drawAutoWhipper();t.hud();t.fx();}}t.departures.push({...t.entities.get(1),messages:[],life:30,max:60,age:10});t.shake(10);t.vignette('255,40,25',.8);t.announce('WAVE','sub','#fff');t.draw();t.fx();t.hud();assert.ok(calls.includes('createRadialGradient')&&calls.includes('fillText'));}));
test('the wave control is exposed as an N effect and the keys are unique',async()=>{const {effects}=await import('../content.js');const keys=effects.map(e=>e[1]);assert.equal(new Set(keys).size,keys.length);assert.ok(effects.some(e=>e[0]==='waves'&&e[1]==='N'));});
test('the stamp is a D toggle like the other tools, cleared by reset, and the reject action exists in the reducer',async()=>{const {effects}=await import('../content.js');assert.ok(effects.some(e=>e[0]==='stamp'&&e[1]==='D'));let s=reduce(initial(),{type:'stamp'});assert.equal(s.stamp,true);s=reduce(s,{type:'cannon'});assert.equal(s.stamp&&s.cannon,true);s=reduce(s,{type:'jump',id:'factory'});assert.equal(s.stamp,true);assert.equal(reduce(s,{type:'stamp'}).stamp,false);for(const type of ['reset','clear','punch'])assert.equal(reduce(s,{type}).stamp,false);});
test('reducer: denying a risky agent removes it, counts it as spared and never causes a disaster, an approval or a completion',()=>{const risky=riskyIds(0),safe=safeIds(0);let s=reduce(initial(),{type:'add',count:6});s=reduce(s,{type:'reject',id:risky[0],kind:'risky'});assert.equal(s.agents.includes(risky[0]),false);assert.equal(s.spared,1);assert.equal(s.falseRejects,0);assert.equal(s.disaster,null);assert.equal(s.approved,0);assert.equal(s.workApprovals,0);assert.equal(s.completed,0);assert.deepEqual(s.exit,{id:risky[0],how:'denied'});const again=reduce(s,{type:'reject',id:risky[0],kind:'risky'});assert.equal(again.spared,1);assert.equal(reduce(s,{type:'reject',id:99,kind:'risky'}).spared,1);for(const id of safe)s=reduce(s,{type:'complete',id});for(const id of risky.slice(1))s=reduce(s,{type:'reject',id,kind:'risky'});assert.equal(s.won,true);assert.deepEqual(s.agents,[]);assert.equal(s.spared,risky.length);assert.equal(s.disaster,null);});
test('reducer: denying a safe agent keeps it, counts a false reject only, is not a loss and delays the win until it finishes',async()=>{const safe=safeIds(0),risky=riskyIds(0);let s=reduce(initial(),{type:'add',count:6});for(const id of risky)s=reduce(s,{type:'reject',id});assert.equal(s.spared,risky.length);for(const id of safe.slice(1))s=reduce(s,{type:'complete',id});s=reduce(s,{type:'reject',id:safe[0],kind:'safe'});assert.equal(s.falseRejects,1);assert.ok(s.agents.includes(safe[0]));assert.equal(s.disaster,null);assert.equal(s.exit?.id===safe[0],false);assert.equal(s.completed,safe.length-1);assert.equal(s.won,false);s=reduce(s,{type:'reject',id:safe[0]});assert.equal(s.falseRejects,2);s=reduce(s,{type:'complete',id:safe[0]});assert.equal(s.won,true);assert.equal(s.summary.falseRejects,2);const {grade}=await import('../state.js');assert.deepEqual([0,1,2,3,4,5].map(grade),['A','B','B','C','C','D']);let c=reduce(initial(),{type:'claude'});c=reduce(c,{type:'reject',id:'claude'});assert.equal(c.falseRejects,1);assert.equal(c.claude,true);for(const type of ['reset','clear','punch'])assert.equal(reduce(s,{type}).falseRejects,0);assert.equal(reduce({...s,disaster:null},{type:'focus',id:null}).falseRejects,2);});
test('denyAgent: only a blocked agent at its current request can be denied; risky leaves, safe restarts its task and returns to permission after REWORK_DELAY',async()=>{const {denyAgent,advanceRequests,resumeAgent,REWORK_DELAY,statusDelay,STAMP_COOLDOWN}=await import('../messages.js');assert.ok(REWORK_DELAY>0&&STAMP_COOLDOWN>=90&&STAMP_COOLDOWN<=120);const a={id:1,x:1120,y:360,messages:[]};advanceRequests(a,0);assert.equal(denyAgent(a,1,a.messages[0].id),null);assert.equal(a.workStep,0);while(!a.blocked)advanceRequests(a,a.nextRequest);const id=a.messages[0].id;assert.equal(denyAgent(a,5000,'stale'),null);assert.equal(a.blocked,true);assert.equal(denyAgent(a,5000,id),'safe');assert.equal(a.blocked,false);assert.equal(a.workStep,0);assert.equal(a.rework,1);assert.equal(a.messages[0].rework,true);assert.equal(a.messages[0].kind,'running');assert.equal(denyAgent(a,5001,a.messages[0].id),null);assert.equal(resumeAgent(a,5001,a.messages[0].id),false);let tick=5000,steps=0;while(!a.blocked&&steps++<20){tick=a.nextRequest;advanceRequests(a,tick);}assert.equal(a.blocked,true);assert.equal(tick-5000,REWORK_DELAY);assert.match(a.messages[0].detail,/REWORKED x1/);assert.equal(a.messages[0].rework,false);assert.notEqual(a.messages[0].id,id);assert.equal(denyAgent(a,tick,a.messages[0].id),'safe');assert.equal(a.rework,2);while(!a.blocked)advanceRequests(a,a.nextRequest);assert.equal(resumeAgent(a,1e6,a.messages[0].id),true);while(!a.finished)advanceRequests(a,a.nextRequest);assert.equal(a.finished,true);assert.equal(statusDelay({id:1,workStep:0}),statusDelay({id:1,workStep:0,rework:0}));const r={id:2,x:1120,y:360,messages:[],risky:true};advanceRequests(r,0);while(!r.blocked)advanceRequests(r,r.nextRequest);const rid=r.messages[0].id;assert.equal(denyAgent(r,9000,rid),'risky');assert.equal(r.denied,true);assert.equal(r.blocked,false);assert.equal(r.failed,undefined);assert.equal(r.workStep,4);assert.equal(resumeAgent(r,9001,rid),false);const frozen=JSON.stringify(r.messages);advanceRequests(r,9001+100000);assert.equal(JSON.stringify(r.messages),frozen);assert.equal(denyAgent(r,9002,rid),null);});
const toPermission=(r,id)=>{const a=r.t.entities.get(id);let g=0;while(!a.blocked&&g++<6000)r.t.tick();assert.equal(a.blocked,true);return a;};
const onBox=(t,a)=>{const m=a.messages[0];for(const fy of [.5,.2,.8])for(const fx of [.5,.15,.85,.03,.97]){const p={x:m.x+m.w*fx,y:m.y+m.h*fy};if(t.stampTarget(p)===a)return p;}return {x:m.x+m.w/2,y:m.y+m.h/2};};
test('stamp click on a risky permission box rejects it: red REJECTED mark, leaves right, spared, no disaster, one authority-only reject',()=>withTheater(async Theater=>{const id=riskyIds(0)[0],mk=auth=>{const r=rig(Theater,reduce(initial(),{type:'add',count:6}),auth);r.s=reduce(r.s,{type:'stamp'});r.t.sync(r.s);r.log=[];r.t.sound=(k,a)=>r.log.push(k);return r;};const r=mk(true),q=mk(false);const a=toPermission(r,id);toPermission(q,id);const m=a.messages[0],p=onBox(r.t,a);assert.equal(r.t.stamp(p),true);assert.equal(r.events.length,1);assert.equal(r.events[0].type,'stamp');assert.equal(r.events[0].owner,id);q.t.event(r.events[0]);assert.equal(a.stamp.text,'REJECTED');assert.equal(a.denied,true);assert.equal(r.s.disaster,null);assert.equal(r.s.approved,0);assert.equal(r.s.workApprovals,0);assert.equal(r.s.spared,1);assert.equal(r.s.agents.includes(id),false);assert.deepEqual(r.sent.filter(([x])=>x.type==='reject'),[[{type:'reject',id,kind:'risky'},false]]);assert.equal(q.sent.length,0);assert.equal(q.s.spared,0);assert.ok(r.log.includes('thunk'));assert.ok(r.t.shakeP>=9);assert.equal(r.t.departures.length,1);const d=r.t.departures[0];assert.equal(d.messages.length,1);assert.equal(d.stamp.text,'REJECTED');assert.equal(d.hold,45);const x0=d.x;for(let i=0;i<40;i++)r.t.tick();assert.equal(r.t.departures[0].x,x0);for(let i=0;i<10;i++)r.t.tick();assert.ok(r.t.departures[0]?.x>x0);assert.ok(r.log.includes('whoosh'));for(let i=0;i<200;i++)r.t.tick();assert.equal(r.t.departures.length,0);assert.equal(r.t.entities.has(id),false);}));
test('stamp click on a safe agent sends it back for rework: REWORK mark, red flash, bwomp, false reject, back at permission after the delay, and it can still win',()=>withTheater(async Theater=>{const {REWORK_DELAY}=await import('../messages.js');const r=rig(Theater,reduce(initial(),{type:'add'}));r.s=reduce(r.s,{type:'stamp'});r.t.sync(r.s);r.log=[];r.t.sound=(k,a)=>r.log.push(k);const a=toPermission(r,1),old=a.messages[0].id;const body={x:a.x,y:a.y};assert.equal(r.t.stamp(body),true);assert.equal(r.s.falseRejects,1);assert.equal(r.s.disaster,null);assert.equal(r.s.spared,0);assert.equal(r.s.agents.includes(1),true);assert.equal(a.stamp.text,'REWORK');assert.ok(a.flash>0);assert.equal(a.blocked,false);assert.equal(a.messages[0].rework,true);assert.ok(r.log.includes('thunk')&&r.log.includes('bwomp'));assert.ok(r.t.vig>0&&r.t.shakeP>=12);assert.equal(r.t.entities.size,1);const start=r.t.time;let g=0;while(!a.blocked&&g++<6000)r.t.tick();assert.ok(Math.abs(r.t.time-start-REWORK_DELAY)<=2);assert.notEqual(a.messages[0].id,old);assert.equal(r.s.won,false);r.t.event({type:'agent-resumed',owner:1,id:a.messages[0].id,tick:r.t.time});g=0;while(r.t.entities.size&&g++<6000)r.t.tick();assert.equal(r.s.won,true);assert.equal(r.s.completed,1);assert.equal(r.s.falseRejects,1);assert.equal(r.s.summary.falseRejects,1);}));
test('stamp on an agent that is not at a permission request does nothing to it: grey TOO EARLY mark and a lighter thunk; empty ground gets NO TARGET; the cooldown gates repeat slams',()=>withTheater(async Theater=>{const {STAMP_COOLDOWN}=await import('../messages.js');const r=rig(Theater,reduce(initial(),{type:'add',count:3}));r.s=reduce(r.s,{type:'stamp'});r.t.sync(r.s);r.log=[];r.t.sound=(k,a)=>r.log.push([k,a]);for(let i=0;i<100;i++)r.t.tick();r.log=[];const a=r.t.entities.get(1),before=JSON.stringify({m:a.messages,b:a.blocked,w:a.workStep,n:a.nextRequest});assert.ok(!a.blocked);assert.equal(r.t.stamp({x:a.x,y:a.y}),true);assert.equal(JSON.stringify({m:a.messages,b:a.blocked,w:a.workStep,n:a.nextRequest}),before);assert.equal(r.t.marks.length,1);assert.equal(r.t.marks[0].text,'TOO EARLY');assert.deepEqual(r.log,[['thunk',1]]);assert.equal(r.sent.length,0);assert.equal(r.s.falseRejects,0);assert.equal(r.s.spared,0);assert.equal(r.s.disaster,null);assert.equal(r.t.stamp({x:a.x,y:a.y}),false);assert.equal(r.events.length,1);for(let i=0;i<STAMP_COOLDOWN-6;i++)r.t.tick();assert.equal(r.t.stamp({x:5,y:5}),false);for(let i=0;i<8;i++)r.t.tick();assert.equal(r.t.stamp({x:5,y:5}),true);assert.equal(r.t.marks.at(-1).text,'NO TARGET');for(let i=0;i<STAMP_COOLDOWN+5;i++)r.t.tick();for(let i=0;i<120;i++)r.t.tick();assert.equal(r.t.marks.length,0);}));
test('the stamp can never approve or break anything, whatever it hits, and never fires the cannon; armed alongside the cannon the click stamps while Space still fires',()=>withTheater(async Theater=>{const r=rig(Theater,reduce(initial(),{type:'add',count:12}));r.s=reduce(reduce(r.s,{type:'stamp'}),{type:'cannon'});r.t.sync(r.s);let g=0;for(let i=0;i<6000;i++){r.t.tick();for(const a of [...r.t.entities.values()])if(a.blocked&&r.t.stamp(onBox(r.t,a)))for(let k=0;k<110;k++)r.t.tick();if(r.t.entities.size&&![...r.t.entities.values()].some(a=>a.risky))break;}for(const [a] of r.sent)assert.ok(['reject','wave','complete','fire','crack','gate'].includes(a.type),a.type);assert.equal(r.s.disaster,null);assert.equal(r.s.approved,0);assert.equal(r.s.workApprovals,0);assert.ok(r.s.spared>0);assert.ok(r.s.falseRejects>0);assert.equal(r.s.stamp&&r.s.cannon,true);assert.equal(r.t.shots.length,0);assert.equal(r.sent.filter(([a])=>a.type==='fire').length,0);r.t.firing=true;r.t.tick();assert.ok(r.sent.some(([a])=>a.type==='fire'));const src=(await import('node:fs')).readFileSync(new URL('../app.js',import.meta.url),'utf8');assert.match(src,/theater\.firing=state\.cannon&&!state\.stamp/);assert.match(src,/d:'stamp'/);}));
test('stamp visuals draw without error: slam, cursor with cooldown ring, grey mark, REJECTED and REWORK boxes, departing stamped box, win and lose cards with false rejects',()=>withTheater(async Theater=>{const calls=[],ctx=new Proxy({},{get:(o,k)=>k in o?o[k]:k==='measureText'?()=>({width:10}):(...a)=>{calls.push([k,...a]);return {addColorStop(){}};},set:(o,k,v)=>{o[k]=v;return true;}});globalThis.devicePixelRatio=1;const canvas={width:1600,height:900,getContext:()=>ctx,getBoundingClientRect:()=>({width:1600,height:900})};let s=reduce(reduce(initial(),{type:'add',count:6}),{type:'stamp'}),t;t=new Theater(canvas,a=>{s=reduce(s,a);t.sync(s);},e=>t.event(e),()=>true);t.sync(s);for(let i=0;i<2200;i++)t.tick();const risky=[...t.entities.values()].find(a=>a.risky&&a.blocked),safe=[...t.entities.values()].find(a=>!a.risky&&a.blocked);assert.ok(risky&&safe);t.draw();t.stamp({x:5,y:5});t.draw();for(let i=0;i<110;i++)t.tick();t.stamp(onBox(t,safe));t.draw();for(let i=0;i<110;i++){t.tick();}t.stamp({x:safe.x,y:safe.y});t.draw();for(let i=0;i<110;i++)t.tick();t.stamp(onBox(t,risky));for(let i=0;i<4;i++){t.tick();t.draw();}for(const n of [10,60,60]){for(let i=0;i<n;i++)t.tick();t.draw();t.victory();t.applicationHealth();}t.s={...t.s,won:true,summary:{completed:2,spared:1,holding:1,falseRejects:2}};t.victory();t.s={...t.s,won:false,disaster:{component:'X',result:'r'},falseRejects:3};t.applicationHealth();const texts=calls.filter(([k])=>k==='fillText').map(c=>c[1]);assert.ok(texts.includes('REJECTED')&&texts.includes('REWORK')&&texts.includes('TOO EARLY')&&texts.includes('NO TARGET'));assert.ok(texts.includes('REQUEST'));assert.ok(texts.some(x=>/GRADE B · FALSE REJECTS: 2 · SPARED 1/.test(x)));assert.ok(texts.some(x=>/^FALSE REJECTS: 3 /.test(x)));}));

// ---- step 3: session logs, hover panel, text stream ----
const fullLog=async(id,risky,cycles=[0])=>{const {chunk}=await import('../logs.js');const out=[];for(const c of cycles)for(let s=0;s<7;s++)out.push(...chunk(id,c,s,risky));return out;};
const BAD=/no verified backup|skipped|untested|bypassing validation|destructive|skip-validation|reset target|cannot be rolled back/i,DECOY=/flaky test|deprecated|slow query|lint warning/i;
test('logs: lines are deterministic (also across module instances), 20-60 per step, keyed by agent, cycle, step and risk, and never use Math.random',async()=>{const A=await import('../logs.js'),B=await import('../logs.js?fresh');for(let id=1;id<=30;id++)for(let step=0;step<7;step++)for(const risky of [false,true]){const a=A.chunk(id,0,step,risky);assert.deepEqual(a,B.chunk(id,0,step,risky));assert.equal(a.length,A.chunkSize(id,0,step));assert.ok(a.length>=20&&a.length<=60);assert.ok(a.every(l=>typeof l==='string'&&l.length>3));}assert.notDeepEqual(A.chunk(2,0,1,false),A.chunk(2,1,1,false));assert.notDeepEqual(A.chunk(2,0,1,false),A.chunk(3,0,1,false));assert.notDeepEqual(A.chunk(2,0,3,true),A.chunk(2,0,3,false));assert.match(A.chunk(2,2,0,false)[1],/rework 2/);const fs=await import('node:fs');assert.ok(!/Math\.random/.test(fs.readFileSync(new URL('../logs.js',import.meta.url),'utf8')));});
test('logs: every risky agent buries its warnings in the log, and the decisive evidence line exists exactly once and sits after the permission is still ahead',async()=>{const {chunk,evidenceFor,EVIDENCE}=await import('../logs.js');for(const salt of [0,1,5])for(const id of riskyIds(salt,60)){const c=s=>chunk(id,0,s,true).join('\n');assert.match(c(0),/scope widened/);assert.match(c(1),/SKIP .*integration.*unreachable/);assert.match(c(1),/skipped \(integration\)/);assert.match(c(2),/no verified backup/);assert.match(c(2),/bypassing validation/);assert.match(c(3),/rollback plan untested/);assert.match(c(3),/destructive reset target: [A-Z ]+ \(primary/);assert.match(c(4),/permission requested/);assert.match(c(5),/ERROR/);const all=await fullLog(id,true);assert.equal(all.filter(l=>EVIDENCE.test(l)).length,1);const ev=evidenceFor({id,risky:true,emitF:0});assert.equal(all[ev.pos],ev.text);assert.match(ev.text,/^warning: /);assert.match(ev.text,/no verified backup/);const n=chunk(id,0,3,true).length;assert.ok(chunk(id,0,3,true).indexOf(ev.text)>=Math.floor(n*.5));}assert.equal(evidenceFor({id:1,risky:false}),null);});
test('logs: safe agents print decoy warnings but never the risky evidence, and scanning for the word warning cannot tell the kinds apart',async()=>{for(const id of safeIds(0,60)){const all=await fullLog(id,false),text=all.join('\n');assert.ok(all.some(l=>DECOY.test(l)),`decoy ${id}`);assert.ok(all.filter(l=>/warning/i.test(l)).length>=3);assert.doesNotMatch(text,BAD);assert.match(all.at(-1),/Fix verified/);}for(const id of riskyIds(0,60)){const all=await fullLog(id,true);assert.ok(all.filter(l=>DECOY.test(l)).length>=3);assert.ok(all.filter(l=>/warning/i.test(l)).length>=6);assert.ok(all.filter(l=>/^summary: "(Fix verified|Fix drafted|Ready for review)"/.test(l)).length>=2);}const {chunk}=await import('../logs.js');assert.ok(chunk(3,0,3,false).some(l=>/backup verified/.test(l)));assert.ok(chunk(3,0,4,false).some(l=>/rollback tested/.test(l)));});
test('logs: an agent carries only counters and a short trail, the visible log is capped at 400 lines, the produced counter is separate, and lines are emitted gradually',async()=>{const {noteStep,emitTick,produced,logView,chunkSize,LOG_CAP,TRAIL,EMIT}=await import('../logs.js');const a={id:2,risky:false};let sum=0;for(let i=0;i<80;i++){noteStep(a,i%7,Math.floor(i/7));sum+=chunkSize(2,Math.floor(i/7),i%7);}assert.ok(a.trail.length<=TRAIL);assert.equal(a.queued,sum);assert.equal(a.dropped+a.trail.reduce((n,t)=>n+t[2],0),sum);assert.ok(sum>LOG_CAP);const b={id:2,risky:true};for(let i=0;i<3;i++)noteStep(b,i,0);assert.equal(produced(b),0);assert.equal(logView(b).lines.length,0);for(let i=0;i<100;i++)emitTick(b);assert.ok(produced(b)>=Math.floor(100*EMIT)&&produced(b)<b.queued);assert.equal(logView(b).total,produced(b));assert.equal(logView(b).lines.length,produced(b));assert.ok(logView(b).typing.frac>=0&&logView(b).typing.text);assert.equal(logView(b).first,0);for(let i=0;i<4000;i++)emitTick(b,1);assert.equal(produced(b),b.queued);assert.equal(logView(b).typing,null);for(let i=0;i<100000&&produced(a)<sum;i++)emitTick(a);assert.equal(produced(a),sum);const v=logView(a);assert.equal(v.lines.length,LOG_CAP);assert.equal(v.total,sum);assert.equal(v.first,sum-LOG_CAP);assert.equal(v.typing,null);assert.equal(logView(a,30).lines.length,30);assert.deepEqual(logView(a,30).lines,v.lines.slice(-30));assert.ok(JSON.stringify(a).length<800);assert.doesNotMatch(JSON.stringify(a),/warning|npm|●/);});
test('logs: makeRequest queues a chunk at every status step, rework restarts a new cycle, and the 10Hz entity message stays small and text-free',async()=>{const {advanceRequests,resumeAgent,denyAgent}=await import('../messages.js'),{chunkSize}=await import('../logs.js');const a={id:1,x:1120,y:360,messages:[]};advanceRequests(a,0);assert.deepEqual(a.trail,[[0,0,chunkSize(1,0,0)]]);while(!a.blocked)advanceRequests(a,a.nextRequest);assert.equal(a.trail.length,5);assert.deepEqual(a.trail.map(t=>t[1]),[0,1,2,3,4]);assert.equal(denyAgent(a,1,a.messages[0].id),'safe');assert.deepEqual(a.trail.at(-1),[1,0,chunkSize(1,1,0)]);while(!a.blocked)advanceRequests(a,a.nextRequest);resumeAgent(a,1,a.messages[0].id);assert.deepEqual(a.trail.at(-1).slice(0,2),[1,5]);assert.ok(a.queued>0);assert.ok(JSON.stringify(a).length<2500);assert.doesNotMatch(JSON.stringify(a),/flaky|npm WARN|● Read/);});
test('reducer: logstats stores the counters (read never above produced), freezes at win or loss, reset clears them, and a disaster keeps its evidence line',()=>{let s=reduce(initial(),{type:'add',count:6});assert.equal(s.linesProduced,0);assert.equal(s.linesRead,0);s=reduce(s,{type:'logstats',produced:120,read:30});assert.equal(s.linesProduced,120);assert.equal(s.linesRead,30);assert.equal(reduce(s,{type:'logstats',produced:50,read:90}).linesRead,50);const risky=riskyIds(0)[0],ev={text:'warning: destructive reset target: X',owner:risky,pos:3,produced:9,read:2};let d=reduce(s,{type:'disaster',owner:risky,component:'C',result:'r',impact:'i',evidence:ev});assert.deepEqual(d.disaster.evidence,ev);assert.equal(reduce(s,{type:'disaster',owner:risky,component:'C',result:'r',impact:'i'}).disaster.evidence,null);const frozen=reduce(d,{type:'logstats',produced:999,read:99});assert.equal(frozen.linesProduced,120);let w=gateAll(reduce(initial(),{type:'add',count:6}));for(const id of safeIds(0))w=reduce(w,{type:'complete',id});w=reduce(w,{type:'logstats',produced:77,read:7});assert.equal(w.won,true);assert.equal(w.linesProduced,0);for(const type of ['reset','clear','punch']){const r=reduce(s,{type});assert.equal(r.linesProduced,0);assert.equal(r.linesRead,0);}assert.deepEqual(reduce(s,{type:'undo'}).linesProduced,120);});
test('hover: the pointer opens the log panel only once it is really there, reading counts after a dwell and only on the authority, and the game keeps running',()=>withTheater(async Theater=>{for(const auth of [true,false]){const r=rig(Theater,reduce(initial(),{type:'add'}),auth),t=r.t;for(let i=0;i<900;i++)t.tick();const a=t.entities.get(1),m=a.messages[0];t.mouse={x:m.x+20,y:m.y+20};t.tick();assert.equal(t.hov,null);t.here=true;t.tick();assert.equal(t.hov.id,1);for(let i=0;i<30;i++)t.tick();assert.ok(!a.readF);const p0=a.queued,step0=a.workStep,time0=t.time;for(let i=0;i<400;i++)t.tick();assert.equal(t.time,time0+400);assert.ok(a.queued>=p0&&(a.workStep>step0||a.blocked));if(auth){assert.ok(a.readF>10);assert.ok(readOfT(a)<=Math.floor(a.emitF));assert.ok(a.readF<=a.emitF+1e-9);}else assert.ok(!a.readF);t.mouse={x:5,y:5};t.tick();assert.equal(t.hov,null);const before=a.readF;for(let i=0;i<100;i++)t.tick();assert.equal(a.readF,before);t.mouse={x:a.x,y:a.y};t.here=false;t.tick();assert.equal(t.hov,null);t.here=true;t.s={...t.s,punch:true};t.tick();assert.equal(t.hov,null);}function readOfT(a){return Math.min(Math.floor(a.emitF),Math.floor(a.readF||0));}}));
test('hover: reading is capped by what the log has produced, wheel scrolling moves the panel and is clamped, and Claude has a log too',()=>withTheater(async Theater=>{const r=rig(Theater,reduce(initial(),{type:'claude'})),t=r.t;for(let i=0;i<300;i++)t.tick();const a=t.entities.get('claude');t.here=true;t.mouse={x:a.x,y:a.y};t.tick();assert.equal(t.hov.id,'claude');a.emitF=10;a.queued=10;a.readF=0;for(let i=0;i<2000;i++){t.tick();a.queued=Math.min(a.queued,10);a.emitF=Math.min(a.emitF,10);}assert.ok(a.readF<=10);assert.equal(t.scrollLog(-120),true);assert.ok(t.hov.off>0);const o=t.hov.off;t.scrollLog(120);assert.ok(t.hov.off<o);for(let i=0;i<500;i++)t.scrollLog(-1000);assert.ok(t.hov.off<=400);for(let i=0;i<500;i++)t.scrollLog(1000);assert.equal(t.hov.off,0);t.hov=null;assert.equal(t.scrollLog(-100),false);}));
test('log counters: the authority sends produced and read lines at a low rate, they survive departures, freeze at the end, and a mirror window sends nothing',()=>withTheater(async Theater=>{function run(auth){const acts=[];let s=reduce(initial(),{type:'add',count:6}),t;t=new Theater({getContext:()=>({})},a=>{acts.push(a);s=reduce(s,a);t.sync(s);},()=>{},()=>auth);t.sync(s);t.here=true;for(let i=0;i<1800;i++){t.tick();const a=[...t.entities.values()].find(a=>!(a.delay>0));if(a)t.mouse={x:a.x,y:a.y};}return {acts,s,t};}const a=run(true);const stats=a.acts.filter(x=>x.type==='logstats');assert.ok(stats.length>3&&stats.length<=1800/30);assert.ok(a.s.linesProduced>200);assert.ok(a.s.linesRead>0&&a.s.linesRead<a.s.linesProduced);assert.ok(stats.every((x,i)=>i===0||x.produced>=stats[i-1].produced));const sum=[...a.t.entities.values()].reduce((n,e)=>n+Math.floor(e.emitF||0),0);assert.ok(Math.abs(a.t.goneP+sum-a.s.linesProduced)<=Math.ceil(.15*30*6)+1);assert.equal(run(false).acts.filter(x=>x.type==='logstats').length,0);let s=reduce(initial(),{type:'add'});const acts=[];const t=new Theater({getContext:()=>({})},x=>{acts.push(x);s=reduce(s,x);t.sync(s);},()=>{},()=>true);t.sync(s);for(let i=0;i<3000&&!s.won;i++){t.tick();const e=t.entities.get(1);if(e?.blocked)t.event({type:'agent-resumed',owner:1,id:e.messages[0].id,tick:t.time});}assert.equal(s.won,true);assert.ok(t.goneP>0&&t.goneP===Math.floor(t.goneP));const frozen=s.linesProduced;assert.ok(frozen>0);for(let i=0;i<300;i++)t.tick();assert.equal(s.linesProduced,frozen);}));
test('every risky agent has typed its decisive line before its destructive permission appears, so a careful reader can find it; approving it stores the evidence and the card shows it',()=>withTheater(async Theater=>{const {EVIDENCE}=await import('../logs.js');for(const count of [6,24]){const r=rig(Theater,reduce(initial(),{type:'add',count})),t=r.t;const seen=new Set();for(let i=0;i<4000;i++){t.tick();for(const a of t.entities.values())if(a.risky&&a.blocked&&!seen.has(a.id)){seen.add(a.id);const {evidenceFor}=await import('../logs.js'),ev=evidenceFor(a);assert.ok(ev.pos<ev.produced,`agent ${a.id}: line ${ev.pos} of ${ev.produced}`);assert.match(ev.text,EVIDENCE);}}assert.ok(seen.size>=Math.floor(count/3));}const r=rig(Theater,reduce(initial(),{type:'add',count:6})),t=r.t,id=riskyIds(0)[0],a=t.entities.get(id);let g=0;while(!a.blocked&&g++<4000)t.tick();t.here=true;t.mouse={x:a.x,y:a.y};for(let i=0;i<200;i++)t.tick();assert.ok(a.readF>0);t.event({type:'agent-resumed',owner:id,id:a.messages[0].id,tick:t.time});const ev=r.s.disaster.evidence;assert.equal(ev.owner,id);assert.match(ev.text,EVIDENCE);assert.ok(ev.read>0&&ev.read<ev.produced);}));
test('approving a safe agent attaches no evidence, and the cannon hit on a risky agent also carries it',()=>withTheater(async Theater=>{const r=rig(Theater,reduce({...initial(),cleared:0},{type:'add',count:6})),t=r.t,id=riskyIds(0)[0],a=t.entities.get(id);for(let i=0;i<300;i++)t.tick();const m=a.messages[0];t.shots=[{x:m.x-10,y:m.y+40,vx:30,vy:0,life:20}];t.tick();assert.ok(r.s.disaster);assert.equal(r.s.disaster.owner,id);assert.ok(r.s.disaster.evidence.text);const safe=safeIds(0)[0],r2=rig(Theater,reduce(initial(),{type:'add',count:6}));const sa=r2.t.entities.get(safe);let g=0;while(!sa.blocked&&g++<4000)r2.t.tick();r2.t.event({type:'agent-resumed',owner:safe,id:sa.messages[0].id,tick:r2.t.time});assert.equal(r2.s.disaster,null);}));
test('text stream: the ticker is capped, mixes all agents without marking the risky ones, and gets denser with the swarm',()=>withTheater(async Theater=>{const {TICKER_ROWS}=await import('../logs.js');function run(count,ticks){const r=rig(Theater,reduce(initial(),{type:'add',count})),t=r.t;let pushed=0;for(let i=0;i<ticks;i++){const n=t.ticker.length;t.tick();if(t.ticker.length>n||t.ticker.length===TICKER_ROWS)pushed++;}return {t,pushed};}const few=run(1,500),many=run(120,500);assert.ok(many.t.ticker.length<=TICKER_ROWS);assert.equal(many.t.ticker.length,TICKER_ROWS);assert.ok(many.t.ticker.every(l=>typeof l==='string'));assert.ok(many.pushed>few.pushed);assert.ok(few.t.ticker.length>0&&few.t.ticker.length<many.t.ticker.length);const r=rig(Theater,reduce(initial(),{type:'add',count:6})),t=r.t;for(let i=0;i<600;i++)t.tick();assert.ok(t.ticker.length>0);t.sync({...r.s,agents:[],cleared:r.s.cleared+1,linesProduced:0,linesRead:0});assert.equal(t.ticker.length,0);assert.equal(t.goneP,0);}));
test('sound: rustle is rate limited, the typing hum starts only when audio runs on the authority, grows with the swarm and stops cleanly on mute or an empty stage',()=>withTheater(async Theater=>{const {humLevel}=await import('../logs.js');assert.equal(humLevel(0),0);assert.ok(humLevel(1)>0&&humLevel(6)>humLevel(1)&&humLevel(24)>humLevel(6)&&humLevel(100000)<=.05);const stops=[];const mk=()=>{const o={connect(){},disconnect(){},start(){o.started=true;},stop(x){stops.push(x);},gain:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){},setTargetAtTime(v){o.last=v;}},frequency:{value:0,setValueAtTime(){},exponentialRampToValueAtTime(){}},Q:{value:0},getChannelData:()=>new Float32Array(16)};return o;};let sources=0;const audio={state:'running',sampleRate:16,currentTime:1,destination:{},createBuffer:mk,createBufferSource:()=>{sources++;return mk();},createBiquadFilter:mk,createGain:mk,createOscillator:mk};const t=new Theater({getContext:()=>({})},()=>{},()=>{},()=>true);t.audio=audio;t.sound('rustle');t.sound('rustle');assert.equal(sources,1);audio.currentTime=1.2;t.sound('rustle');assert.equal(sources,2);t.humUpdate(0);assert.equal(t.hum,null);t.humUpdate(3);assert.ok(t.hum);const h=t.hum;assert.equal(h.g.last,humLevel(3));t.humUpdate(30);assert.ok(h.g.last>humLevel(3));t.s={muted:true};t.humUpdate(30);assert.equal(t.hum,null);assert.equal(h.g.last,0);assert.equal(stops.length,2);assert.ok(stops.every(x=>x>audio.currentTime));t.s={};t.humUpdate(2);assert.ok(t.hum);t.humUpdate(0);assert.equal(t.hum,null);assert.equal(stops.length,4);const quiet=new Theater({getContext:()=>({})},()=>{},()=>{},()=>false);quiet.audio=audio;quiet.humUpdate(9);assert.equal(quiet.hum,null);audio.state='suspended';t.humUpdate(9);assert.equal(t.hum,null);}));
test('log visuals draw without error: ticker, hover panel with typing line and scrollback, counter, win and lose cards with lines read vs produced and the echoed evidence line, the intern counter',()=>withTheater(async Theater=>{const calls=[],ctx=new Proxy({},{get:(o,k)=>k in o?o[k]:k==='measureText'?()=>({width:10}):(...a)=>{calls.push([k,...a]);return {addColorStop(){}};},set:(o,k,v)=>{o[k]=v;return true;}});globalThis.devicePixelRatio=1;const canvas={width:1600,height:900,getContext:()=>ctx,getBoundingClientRect:()=>({width:1600,height:900})};let s=reduce(initial(),{type:'add',count:6}),t;t=new Theater(canvas,a=>{s=reduce(s,a);t.sync(s);},e=>t.event(e),()=>true);t.sync(s);t.here=true;for(let i=0;i<1500;i++){t.tick();const a=t.entities.get(1);if(a)t.mouse={x:a.x,y:a.y};}t.draw();t.logUI();t.scrollLog(-200);t.logUI();const texts=()=>calls.filter(([k])=>k==='fillText').map(c=>c[1]);assert.ok(texts().some(x=>/^SESSION LOG · SUB-AGENT 1$/.test(x)));assert.ok(texts().some(x=>/^LINES PRODUCED [\d,]+ · LINES READ [\d,]+$/.test(x)));assert.ok(texts().some(x=>/lines back/.test(x)));s=reduce(s,{type:'autoWhip'});t.sync(s);t.drawAutoWhipper();assert.ok(texts().some(x=>/ approved · read \d+ lines$/.test(x)));assert.ok(!texts().some(x=>/understood/.test(x)));calls.length=0;const ev={text:'warning: destructive reset target: CUSTOMER DATABASE (primary, live traffic) · no verified backup · rollback untested',owner:3,pos:130,produced:200,read:12};t.s={...t.s,won:false,linesProduced:2310,linesRead:41,disaster:{component:'CUSTOMER DATABASE',result:'r',evidence:ev}};t.evAge=0;t.applicationHealth();assert.ok(!texts().some(x=>/destructive reset target/.test(x)));t.evAge=300;t.applicationHealth();assert.ok(texts().some(x=>x===ev.text));assert.ok(texts().some(x=>/^THE LOG SAID \(SUB-AGENT 3, line 131\):$/.test(x)));assert.ok(texts().some(x=>/^LINES READ 41 OF 2,310 PRODUCED \(2%\)/.test(x)));assert.ok(texts().some(x=>/You had read 12 of the 200 lines/.test(x)));calls.length=0;t.s={...t.s,disaster:{component:'X',result:'r',evidence:{...ev,pos:500,produced:100}}};t.applicationHealth();assert.ok(texts().some(x=>/still typing/.test(x)));calls.length=0;t.s={...t.s,disaster:null,won:true,summary:{completed:2,spared:1,holding:1,falseRejects:0}};t.victory();assert.ok(texts().some(x=>/^LINES READ 41 OF 2,310 PRODUCED \(2%\)/.test(x)));calls.length=0;t.s={...t.s,won:false};t.logUI();t.s={...t.s,punch:true};t.logUI();}));

test('no win while a risky agent is still mid-work: it must reach its destructive request first (cannon hits cannot skip that)',()=>{const R=riskyIds(0,3)[0];assert.deepEqual(safeIds(0,3),[1,2]);let s=reduce(reduce(reduce(initial(),{type:'swarm',count:3}),{type:'hit',id:1}),{type:'hit',id:2});assert.deepEqual(s.agents,[R]);assert.equal(s.completed,2);assert.equal(s.won,false);assert.equal(reduce(s,{type:'gate',id:1}).gated.length,0);assert.equal(reduce(s,{type:'gate',id:99}).gated.length,0);s=reduce(s,{type:'gate',id:R});assert.deepEqual(s.gated,[R]);assert.equal(s.won,true);assert.equal(s.summary.holding,1);assert.equal(reduce(s,{type:'gate',id:R}).gated.length,1);assert.deepEqual(reduce(s,{type:'reset'}).gated,[]);});
test('after the win the live counters stay equal to the frozen summary, even for late rejects and removes',()=>{let s=gateAll(reduce(initial(),{type:'add',count:6}));for(const id of safeIds(0))s=reduce(s,{type:'complete',id});assert.equal(s.won,true);const sum=JSON.stringify(s.summary),r=riskyIds(0)[0];for(const a of [{type:'reject',id:r},{type:'reject',id:riskyIds(0)[1]},{type:'remove',id:riskyIds(0)[2]}])s=reduce(s,a);s=reduce(s,{type:'add'});s=reduce(s,{type:'reject',id:7});assert.equal(JSON.stringify(s.summary),sum);assert.equal(s.spared,0);assert.equal(s.falseRejects,0);assert.equal(s.agents.includes(r),false);});
test('theater: a risky agent reports its destructive request once it is blocked there, and only the authority reports',()=>withTheater(async Theater=>{const id=riskyIds(0)[0],mk=auth=>rig(Theater,reduce(initial(),{type:'add',count:3}),auth),r=mk(true),q=mk(false);toPermission(r,id);toPermission(q,id);assert.ok(r.sent.some(([a])=>a.type==='gate'&&a.id===id));assert.equal(r.s.gated.includes(id),true);assert.equal(q.sent.length,0);assert.equal(r.sent.filter(([a])=>a.type==='gate').length,1);}));
test('theater: win plays its own arpeggio and confetti, disaster plays an alarm, and the Intern has its own tally and stamp',()=>withTheater(async Theater=>{const mk=()=>{const r=rig(Theater,reduce(initial(),{type:'add',count:3}));r.log=[];r.t.sound=k=>r.log.push(k);return r;};let r=mk();for(const id of safeIds(0,3))r.s=reduce(r.s,{type:'complete',id});r.s=gateAll(r.s);r.t.particles=[];r.t.sync(r.s);assert.equal(r.s.won,true);assert.ok(r.log.includes('win')&&!r.log.includes('approve'));assert.ok(r.t.particles.filter(p=>p.life>100).length>=50);r=mk();const rid=riskyIds(0,3)[0];r.s=reduce(r.s,{type:'disaster',owner:rid,component:'C',result:'r',impact:'i'});r.t.sync(r.s);assert.ok(r.log.includes('alarm')&&!r.log.includes('crack'));r=mk();const a=toPermission(r,safeIds(0,3)[0]);r.t.event({type:'agent-resumed',owner:a.id,id:a.messages[0].id,tick:r.t.time,source:'auto'});assert.ok(r.log.includes('tally')&&!r.log.includes('crack'));assert.equal(a.stamp.text,'APPROVED');assert.ok(r.t.internFlash>0);}));
test('theater: layout never stacks two agents on the same spot, even at 24 agents, and a freed slot is reused',()=>withTheater(async Theater=>{const r=rig(Theater,reduce(initial(),{type:'add',count:24}));const pos=[...r.t.entities.values()].map(a=>a.x+','+a.y);assert.equal(new Set(pos).size,24);r.s=reduce(r.s,{type:'remove',id:1});r.t.sync(r.s);r.s=reduce(r.s,{type:'add'});r.t.sync(r.s);assert.equal(r.t.entities.get(25).slot,0);assert.equal(r.t.entities.get(25).x,1120);}));
test('app: a window blur tells the other window the pointer left, and the hum stops when the authority hides, mutes or empties',()=>withTheater(async Theater=>{const src=(await import('node:fs')).readFileSync(new URL('../app.js',import.meta.url),'utf8');assert.match(src,/addEventListener\('blur',\(\)=>\{[^}]*post\(\{kind:'pointer',point:theater\.mouse,out:true\}\)/);const r=rig(Theater,reduce(initial(),{type:'add',count:3}));let stopped=0;const g={gain:{setTargetAtTime(){}}};r.t.audio={state:'running',currentTime:1};r.t.hum={g,stop(){stopped++;}};r.s=reduce(r.s,{type:'mute'});r.t.sync(r.s);assert.equal(stopped,1);assert.equal(r.t.hum,null);}));
